import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

path = "budget.xlsx"
z = zipfile.ZipFile(path)
print("Archive parts:")
for n in z.namelist():
    print("  ", n)

wbxml = ET.fromstring(z.read("xl/workbook.xml"))
rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
relmap = {r.attrib["Id"]: r.attrib["Target"] for r in rels}

sheets = []
for s in wbxml.findall(".//m:sheet", NS):
    rid = s.attrib["{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id"]
    sheets.append((s.attrib["name"], relmap[rid].lstrip("/")))
print("\nSheets:", sheets)

shared = []
if "xl/sharedStrings.xml" in z.namelist():
    sst = ET.fromstring(z.read("xl/sharedStrings.xml"))
    for si in sst.findall("m:si", NS):
        shared.append("".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t")))

def col_to_idx(ref):
    letters = "".join(ch for ch in ref if ch.isalpha())
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch.upper()) - 64)
    return idx

def cell_value(c):
    t = c.attrib.get("t")
    v = c.find("m:v", NS)
    raw = v.text if v is not None else None
    if raw is None:
        return None
    if t == "s":
        return shared[int(raw)]
    if t == "b":
        return raw == "1"
    if t == "inlineStr":
        isel = c.find("m:is", NS)
        return "".join(x.text or "" for x in isel.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
    return raw  # numeric stays as string; parse later

for name, target in sheets:
    if not target.startswith("xl/"):
        target = "xl/" + target
    sheetxml = ET.fromstring(z.read(target))
    rows = []
    maxc = 0
    for row in sheetxml.findall(".//m:sheetData/m:row", NS):
        cells = {}
        for c in row.findall("m:c", NS):
            ref = c.attrib["r"]
            ci = col_to_idx(ref)
            cells[ci] = cell_value(c)
            maxc = max(maxc, ci)
        rows.append(cells)
    print(f"\n--- Sheet: {name} rows={len(rows)} max_col={maxc} ---")
    for i, cells in enumerate(rows, start=1):
        if cells:
            print(i, cells)

