                rows.setdefault(row_idx(ref), {})[col_idx(ref)] = val
            if f is not None:
                formulas[ref] = f.text

    print("Formulas found:", formulas if formulas else "none")

    # Locate EXPENSES section: rows between 'EXPENSES' label and 'Total Expenses' label
    labels = {r: {c: str(val) for c, val in cols.items()} for r, cols in rows.items()}
