    print("Formulas found:", formulas if formulas else "none")

    # Locate EXPENSES section: rows between 'EXPENSES' label and 'Total Expenses' label
    labels = {r: {c: str(val) for c, val in cols.items()} for r, cols in rows.items()}
    exp_start = exp_end = None
    for r in sorted(labels):
        text = ' '.join(labels[r].values()).lower()
        if exp_start is None and 'expenses' in text:
            exp_start = r
        elif exp_start is not None and 'total expenses' in text:
            exp_end = r
            break

    grand_total = 0.0
    by_cat = {}
    print(f"\nExpense rows (sheet rows {exp_start + 1} to {exp_end - 1}):")
    for r in range(exp_start + 1, exp_end):
        cols = rows.get(r, {})
        cat = str(cols.get(0, ''))
        sub = str(cols.get(1, ''))
        amt = cols.get(2)
        if amt is not None:
            try:
                amt = float(amt)
            except ValueError:
                amt = None
        if amt is not None:
            grand_total += amt
            by_cat[cat] = by_cat.get(cat, 0.0) + amt
            print(f"  {cat} | {sub} | {amt}")
        else:
            print(f"  {cat} | {sub} | {amt} (non-numeric)")

    print("\nSubtotals by category:")
    for cat, tot in by_cat.items():
        print(f"  {cat}: {tot}")
    print(f"\nTOTAL EXPENSES ACROSS ALL CATEGORIES: {grand_total}")
